create table if not exists public.dashboard_preferences (user_id uuid primary key references auth.users(id) on delete cascade, template text not null default 'EXECUTIVE', widgets jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now()); alter table public.dashboard_preferences enable row level security; drop policy if exists dashboard_preferences_self on public.dashboard_preferences; create policy dashboard_preferences_self on public.dashboard_preferences for all using (user_id=auth.uid()) with check (user_id=auth.uid()); grant select,insert,update,delete on public.dashboard_preferences to authenticated;
create or replace function public.close_zakat_cycle(p_cycle_id uuid, p_final_assessment_id uuid) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_user uuid:=auth.uid(); v_due numeric; v_cycle_no int; begin if v_user is null then raise exception 'UNAUTHORIZED'; end if; select zakat_due into v_due from zakat_assessments where id=p_final_assessment_id and user_id=v_user and hawl_cycle_id=p_cycle_id; if v_due is null then raise exception 'FINAL_ASSESSMENT_NOT_IN_CYCLE'; end if; update zakat_hawl_cycles set status='CLOSED',final_assessment_id=p_final_assessment_id,final_zakat_due=v_due,closed_at=now(),assessment_id=p_final_assessment_id where id=p_cycle_id and user_id=v_user and status in ('OPEN','ACTIVE'); if not found then raise exception 'ACTIVE_CYCLE_NOT_FOUND'; end if; update zakat_assessments set assessment_kind=case when id=p_final_assessment_id then 'FINAL' else assessment_kind end where user_id=v_user and hawl_cycle_id=p_cycle_id; return p_cycle_id; end $$; grant execute on function public.close_zakat_cycle(uuid,uuid) to authenticated;